#[cfg(test)]
mod capability_baseline {
    use super::*;
    #[test]
    fn named_and_local_routes_must_not_bypass_capabilities() {
        let models=serde_json::from_value(json!({"plain":{"hops":{"ollama":"plain"},"chain":["ollama"],"tier":"free","context":8000,"caps":{"tools":false,"input":["text"]}}})).unwrap();
        let providers=vec![Provider{name:"ollama".into(),kind:"ollama".into(),base:"http://127.0.0.1:1".into(),key:String::new(),free:true,oauth:None,num_ctx:None}];
        let catalog=Catalog::new(models,providers).unwrap();
        let body=json!({"messages":[{"role":"user","content":[{"type":"image_url","image_url":{"url":"fixture-image"}}]}],"tools":[{"type":"function","function":{"name":"check","parameters":{"type":"object"}}}]});
        let actual=[("plain",false),("plain",true),("auto",false)].map(|(name,strict)|catalog.candidates(name,&body,strict).len());
        assert_eq!(actual,[0,0,0],"named, strict and local-last-resort routes must all meet required tools/vision support");
    }
}
